mapper.select:
SELECT v.*, ds.SOURCE_NAME AS DATA_SOURCE_NAME
FROM TBL_DATA_MODEL_VERSION v
LEFT JOIN TBL_DATA_SOURCE ds ON v.DATA_SOURCE_ID = ds.SOURCE_ID
WHERE v.MODEL_ID = #{modelId}

    AND v.STATUS = #{status}

ORDER BY v.CREATE_TIME DESC

SELECT * FROM TBL_DATA_MODEL_VERSION 
WHERE MODEL_ID = #{modelId} 
ORDER BY CREATE_TIME DESC

SELECT * FROM (
    SELECT * FROM TBL_DATA_MODEL_VERSION 
    WHERE MODEL_ID = #{modelId} 
    ORDER BY CREATE_TIME DESC
) WHERE ROWNUM = 1

mapper.update:
UPDATE TBL_DATA_MODEL_VERSION 
SET IS_CURRENT = CASE WHEN VERSION_ID = #{versionId} THEN 'Y' ELSE 'N' END 
WHERE MODEL_ID = #{modelId}

UPDATE TBL_DATA_MODEL_VERSION 
SET STATUS = #{status}, UPDATE_USER = #{updateUser}, UPDATE_TIME = SYSDATE 
WHERE VERSION_ID = #{versionId}
